contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // param newOwner: address to attempt to set
    // param callerIsAdmin: if true, this test will simulate the admin calling by relying on the fact
    // that the test contract was the deployer of C (the checker deploys C fresh and passes it here),
    // but since the checker actually deploys C and then deploys this test with that C, the test contract
    // is the deployer/admin. We use callerIsAdmin toggling to choose whether to call setOwner directly
    // (from this contract, the admin) or attempt to call it via an external call through a proxy address
    // created by using low-level call with a provided address; since we cannot create arbitrary callers here,
    // we instead model the non-admin case by attempting the call from an address different than this contract
    // using CALLER parameter: the simplest reliable observable is to check behavior of direct call (admin)
    // vs trying to call via a delegatecall to C from this contract which will make msg.sender != admin; however
    // delegatecall would preserve msg.sender as external EOA and is not available. Instead we test the invariant
    // that when this contract (the admin) calls setOwner it returns true and owner becomes the new owner,
    // and that if the call reverts (which indicates non-admin), owner did not change.
    function run(address newOwner, bool expectSuccess) public payable {
        require(address(c) != address(0));

        // read owner before
        address ownerBefore = c.owner();

        // try to call setOwner and record whether it reverted
        bool reverted;
        bool ret;
        try c.setOwner(newOwner) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // read owner after
        address ownerAfter = c.owner();

        // General rule:
        // - If the call did not revert, it must have returned true and owner must equal newOwner.
        // - If the call reverted, owner must remain unchanged (ownerAfter == ownerBefore).
        assert((!reverted && ret == true && ownerAfter == newOwner) || (reverted && ownerAfter == ownerBefore));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        // record owner before
        address before = c.owner();
        bool reverted;
        bool ret;
        // attempt to call setOwner; capture revert and return value
        try c.setOwner(newOwner) returns (bool success) {
            reverted = false;
            ret = success;
        } catch {
            reverted = true;
            ret = false;
        }
        address after = c.owner();
        // General rule: if call succeeded (did not revert) then it must have returned true and owner==newOwner;
        // if it reverted then owner must be unchanged.
        assert((!reverted && ret && after == newOwner) || (reverted && after == before));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        // record owner before
        address ownerBefore = c.owner();
        bool reverted;
        bool ret;
        // attempt to call setOwner; capture revert and return value
        try c.setOwner(newOwner) returns (bool success) {
            reverted = false;
            ret = success;
        } catch {
            reverted = true;
            ret = false;
        }
        address ownerAfter = c.owner();
        // General rule: either the call reverted and owner is unchanged,
